import java.util.ArrayList;
import java.util.List;

public class Main {
    public static void main(String[] args) {
        Pasangan<String, Integer> ujian = new Pasangan<>("Budi", 90);
        Pasangan<String, Double> produk = new Pasangan<>("KOPI01", 15000.0);

        System.out.println(ujian.getKunci() + " mendapat " + ujian.getNilai());
        System.out.println(produk.getKunci() + " harganya " + produk.getNilai());

        List<Pasangan<String, Integer>> stok = new ArrayList<>();
        stok.add(new Pasangan<>("pensil", 12));
        stok.add(new Pasangan<>("buku", 5));
        int total = 0;
        for (Pasangan<String, Integer> p : stok) {
            System.out.println(p.getKunci() + ": " + p.getNilai());
            total += p.getNilai();
        }
        System.out.println("Total barang: " + total);
    }
}

